static MOD_UNUSED int part_count(int kind) {
    if (API->particles == 0) return 0;
    if (kind < 0) {
        return API->particles->Count(SELF, AMOD_PARTICLE_KIND_POOL_0)
             + API->particles->Count(SELF, AMOD_PARTICLE_KIND_POOL_1)
             + API->particles->Count(SELF, AMOD_PARTICLE_KIND_POOL_2)
             + API->particles->Count(SELF, AMOD_PARTICLE_KIND_UNI);
    }
    return API->particles->Count(SELF, (AmodParticleKind)kind);
}

static MOD_UNUSED int part_capacity(int kind) {
    if (API->particles == 0) return 0;
    if (kind < 0) {
        return API->particles->Capacity(SELF, AMOD_PARTICLE_KIND_POOL_0) * 3
             + API->particles->Capacity(SELF, AMOD_PARTICLE_KIND_UNI);
    }
    return API->particles->Capacity(SELF, (AmodParticleKind)kind);
}

static MOD_UNUSED int part_pick_at(int kind, int at) {
    int k, rem;
    if (API->particles == 0 || at < 0) { g_part_sel = 0; return 0; }
    if (kind >= 0) {
        g_part_sel = API->particles->At(SELF, (AmodParticleKind)kind, at);
        return g_part_sel != 0;
    }
    rem = at;
    for (k = AMOD_PARTICLE_KIND_POOL_0; k <= AMOD_PARTICLE_KIND_UNI; ++k) {
        int n = API->particles->Count(SELF, (AmodParticleKind)k);
        if (rem < n) {
            g_part_sel = API->particles->At(SELF, (AmodParticleKind)k, rem);
            return g_part_sel != 0;
        }
        rem -= n;
    }
    g_part_sel = 0;
    return 0;
}

static MOD_UNUSED int part_pick_tagged(uint32_t tag, int match_index) {
    int k, at, seen = 0;
    if (API->particles == 0 || tag == 0 || match_index < 0) { g_part_sel = 0; return 0; }
    for (k = AMOD_PARTICLE_KIND_POOL_0; k <= AMOD_PARTICLE_KIND_UNI; ++k) {
        for (at = 0; ; ++at) {
            AmodParticle p = API->particles->At(SELF, (AmodParticleKind)k, at);
            if (p == 0) break;
            if (API->particles->GetTag(SELF, p) == tag) {
                if (seen == match_index) { g_part_sel = p; return 1; }
                ++seen;
            }
        }
    }
    g_part_sel = 0;
    return 0;
}

static MOD_UNUSED int part_count_tagged(uint32_t tag) {
    int k, at, total = 0;
    if (API->particles == 0 || tag == 0) return 0;
    for (k = AMOD_PARTICLE_KIND_POOL_0; k <= AMOD_PARTICLE_KIND_UNI; ++k) {
        for (at = 0; ; ++at) {
            AmodParticle p = API->particles->At(SELF, (AmodParticleKind)k, at);
            if (p == 0) break;
            if (API->particles->GetTag(SELF, p) == tag) ++total;
        }
    }
    return total;
}

static MOD_UNUSED int part_kind_of(void) {
