static MOD_UNUSED int part_read(AmodParticleDesc* out) {
    if (API->particles == 0 || g_part_sel == 0) return 0;
    memset(out, 0, sizeof *out);
    out->structSize = sizeof *out;
    return API->particles->Get(SELF, g_part_sel, out);
}

static MOD_UNUSED float part_num(int field) {
    AmodParticleDesc d;
    if (part_read(&d) == 0) return 0.0f;
    switch (field) {
        case 0: return d.position[0];
        case 1: return d.position[1];
        case 2: return d.position[2];
        case 3: return d.direction[0];
        case 4: return d.direction[1];
        case 5: return d.direction[2];
        case 6: return d.speed;
        case 7: return d.size;
        case 8: return d.life;
        case 9: return d.decay;
        case 10: return d.colour[0];
        case 11: return d.colour[1];
        case 12: return d.colour[2];
        case 13: return d.colour[3];
        case 14: return d.gravity[0];
        case 15: return d.gravity[1];
        case 16: return d.gravity[2];
        case 17: return d.speedGrow;
        case 18: return d.sizeGrow;
        case 19: return d.angle;
        case 20: return d.spin;
        case 21: return d.glyphScale[0];
        case 22: return d.glyphScale[1];
        case 23: return d.waypoint;
        default: return 0.0f;
    }
}

static MOD_UNUSED int part_int(int field) {
    AmodParticleDesc d;
    if (part_read(&d) == 0) return 0;
    switch (field) {
        case 0: return d.shape;
        case 1: return d.model;
        case 2: return d.modelFrame;
        case 3: return d.parent;
        default: return 0;
    }
}

static MOD_UNUSED void part_norm3(float dx, float dy, float dz, float out[3]) {
    float len = sqrtf(dx * dx + dy * dy + dz * dz);
    if (len > 0.00001f) { out[0] = dx / len; out[1] = dy / len; out[2] = dz / len; }
    else { out[0] = 0.0f; out[1] = 0.0f; out[2] = 0.0f; }
}

static MOD_UNUSED float part_text_scale(int axis) {
    float s[2] = { 0.0f, 0.0f };
    if (axis < 0 || axis > 1 || API->particles == 0) return 0.0f;
    return API->particles->TextScale(SELF, s) != 0 ? s[axis] : 0.0f;
}

static MOD_UNUSED int part_text_font(void) {
