static MOD_UNUSED void part_spawn_sprite(int kind, int shape, const char* texA, const char* texB, float x, float y, float z, float dx, float dy, float dz, float speed, float size, float life, float decay, float r, float g, float b, float a) {
    AmodParticleDesc d;
    AmodParticle p;
    if (API->particles == 0) return;
    memset(&d, 0, sizeof d);
    d.structSize = sizeof d;
    d.kind = (AmodParticleKind)kind;
    d.shape = shape;
    d.position[0] = x; d.position[1] = y; d.position[2] = z;
    part_norm3(dx, dy, dz, d.direction);
    d.speed = speed;
    d.size = size;
    d.life = life;
    d.decay = decay;
    d.colour[0] = r; d.colour[1] = g; d.colour[2] = b; d.colour[3] = a;
    if (texA != 0 && texA[0] != 0) d.textureA = texture_any(texA);
    if (texB != 0 && texB[0] != 0) d.textureB = texture_any(texB);
    p = API->particles->Spawn(SELF, &d);
    if (p != 0) g_part_sel = p;
}

