    d.shape = AMOD_PARTICLE_SHAPE_MODEL;
    d.model = font;
    d.modelFrame = frame;
    d.glyphScale[0] = ts[0] * scale;
    d.glyphScale[1] = ts[1] * scale;
    d.position[0] = x; d.position[1] = y; d.position[2] = z;
    part_norm3(dx, dy, dz, d.direction);
    d.speed = speed;
    d.size = 0.2f * scale;
    d.life = life;
    d.decay = decay;
    d.colour[0] = r; d.colour[1] = g; d.colour[2] = b; d.colour[3] = a;
