static MOD_UNUSED int part_anim_id(const char* name) {
    int i;
    if (name == 0 || name[0] == 0) return 0;
    for (i = 0; i < PartMaxAnims; ++i) {
        if (g_part_anim_name[i][0] != 0 && strcmp(g_part_anim_name[i], name) == 0)
            return g_part_anim_id[i];
    }
    return 0;
}

static MOD_UNUSED void part_anim_create(const char* name, const char* list) {
    int ids[PartMaxFrames];
    char token[128];
    int count = 0, slot = -1, i;
    const char* p;
    if (API->particles == 0 || name == 0 || name[0] == 0 || list == 0) return;
    if (strlen(name) >= sizeof g_part_anim_name[0]) return;
    for (i = 0; i < PartMaxAnims; ++i) {
        if (g_part_anim_name[i][0] != 0 && strcmp(g_part_anim_name[i], name) == 0) return;
        if (g_part_anim_name[i][0] == 0 && slot < 0) slot = i;
    }
    if (slot < 0) return;
    p = list;
    while (*p != 0 && count < PartMaxFrames) {
        size_t len = 0;
        while (*p == ' ' || *p == '\t' || *p == ';' || *p == ',') ++p;
        if (*p == 0) break;
        while (p[len] != 0 && p[len] != ';' && p[len] != ',') ++len;
        while (len > 0 && (p[len - 1] == ' ' || p[len - 1] == '\t')) --len;
        if (len > 0 && len < sizeof token) {
            AmodTextureId tid;
            memcpy(token, p, len);
            token[len] = 0;
            tid = texture_any(token);
            if (tid != AMOD_INVALID_TEXTURE) ids[count++] = (int)tid;
        }
        p += len;
        while (*p != 0 && *p != ';' && *p != ',') ++p;
    }
    if (count <= 0) return;
    i = API->particles->CreateAnimation(SELF, ids, count);
    if (i > 0) {
        strcpy(g_part_anim_name[slot], name);
        g_part_anim_id[slot] = i;
    }
}

