        for (k = AMOD_PARTICLE_KIND_POOL_0; k <= AMOD_PARTICLE_KIND_UNI; ++k)
            API->particles->Clear(SELF, (AmodParticleKind)k);
    } else {
        API->particles->Clear(SELF, (AmodParticleKind)kind);
    }
}

static MOD_UNUSED int __cdecl part_think_dispatch(AmodParticle particle, float delta, void* user) {
    AmodParticle prev = g_part_sel;
    int alive = 1, i;
    g_part_sel = particle;
    g_part_last_think_dt = delta;
    for (i = 0; i < g_part_think_count; ++i) {
        if (g_part_thinks[i] != 0 && g_part_thinks[i](particle, delta, user) == 0) {
            alive = 0;
            break;
        }
    }
    g_part_sel = prev;
    return alive;
}

static MOD_UNUSED void part_bind_think(AmodParticleThink fn) {
    int i;
    if (fn == 0) return;
    for (i = 0; i < g_part_think_count; ++i) {
        if (g_part_thinks[i] == fn) return;
    }
    if (g_part_think_count < PartMaxHandlers) g_part_thinks[g_part_think_count++] = fn;
}

static MOD_UNUSED void part_attach_think(void) {
