            AmodParticle p = API->particles->At(SELF, (AmodParticleKind)k, at);
            if (p == 0) break;
            if (API->particles->GetTag(SELF, p) == tag) API->particles->ClearThink(SELF, p);
        }
    }
}

static MOD_UNUSED int __cdecl part_birth_dispatch(AmodParticle particle, AmodParticleKind kind, void* user) {
    AmodParticle prev = g_part_sel;
    int allow = 1, i;
    g_part_sel = particle;
    g_part_last_birth_kind = (int)kind;
    for (i = 0; i < g_part_birth_count; ++i) {
        if (g_part_births[i] != 0 && g_part_births[i](particle, kind, user) == 0) {
            allow = 0;
            break;
        }
    }
    g_part_sel = prev;
    return allow;
}

static MOD_UNUSED void part_bind_birth(AmodParticleBirthHandler fn) {
    int i;
    if (fn == 0 || API->particles == 0) return;
    for (i = 0; i < g_part_birth_count; ++i) {
        if (g_part_births[i] == fn) {
            API->particles->SetBirthHandler(SELF, part_birth_dispatch, 0);
            return;
        }
    }
    if (g_part_birth_count < PartMaxHandlers) g_part_births[g_part_birth_count++] = fn;
    API->particles->SetBirthHandler(SELF, part_birth_dispatch, 0);
}

static MOD_UNUSED int __cdecl part_spawn_dispatch(AmodParticleDesc* desc, void* user) {
    int allow = 1, i;
    if (desc != 0) g_part_last_trail = *desc;
    for (i = 0; i < g_part_spawn_count; ++i) {
        if (g_part_spawns[i] != 0 && g_part_spawns[i](desc, user) == 0) {
            allow = 0;
            break;
        }
    }
    if (desc != 0) g_part_last_trail = *desc;
    return allow;
}

static MOD_UNUSED void part_bind_spawn(AmodParticleSpawnHandler fn) {
    int i;
    if (fn == 0 || API->particles == 0) return;
    for (i = 0; i < g_part_spawn_count; ++i) {
        if (g_part_spawns[i] == fn) {
            API->particles->SetSpawnHandler(SELF, part_spawn_dispatch, 0);
            return;
        }
    }
    if (g_part_spawn_count < PartMaxHandlers) g_part_spawns[g_part_spawn_count++] = fn;
    API->particles->SetSpawnHandler(SELF, part_spawn_dispatch, 0);
}

static MOD_UNUSED void part_trail_set_pos(AmodParticleDesc* desc, float x, float y, float z) {
    if (desc == 0) return;
    desc->position[0] = x; desc->position[1] = y; desc->position[2] = z;
}

static MOD_UNUSED int __cdecl part_draw_dispatch(void* user) {
    int skip = 0, i;
    for (i = 0; i < g_part_draw_count; ++i) {
        if (g_part_draws[i] != 0 && g_part_draws[i](user) != 0) skip = 1;
    }
    return skip;
}

static MOD_UNUSED void part_bind_draw(AmodParticleDrawHandler fn) {
    int i;
    if (fn == 0 || API->particles == 0) return;
    for (i = 0; i < g_part_draw_count; ++i) {
        if (g_part_draws[i] == fn) {
            API->particles->SetDrawHandler(SELF, part_draw_dispatch, 0);
            return;
        }
    }
    if (g_part_draw_count < PartMaxHandlers) g_part_draws[g_part_draw_count++] = fn;
    API->particles->SetDrawHandler(SELF, part_draw_dispatch, 0);
}

static MOD_UNUSED void part_restore_handlers(void) {
    if (API->particles == 0) return;
    if (g_part_birth_count > 0) API->particles->SetBirthHandler(SELF, part_birth_dispatch, 0);
    if (g_part_spawn_count > 0) API->particles->SetSpawnHandler(SELF, part_spawn_dispatch, 0);
    if (g_part_draw_count > 0) API->particles->SetDrawHandler(SELF, part_draw_dispatch, 0);
}

static MOD_UNUSED int part_ev_birth_kind(void) {
    return g_part_last_birth_kind;
}

static MOD_UNUSED float part_ev_think_dt(void) {
    return g_part_last_think_dt;
}

static MOD_UNUSED float part_ev_trail_num(int which) {
    if (which >= 0 && which < 3) return g_part_last_trail.position[which];
    return g_part_last_trail.waypoint;
}
